(()=>{'use strict';const E=x=>(window.esc?esc(x):String(x??''));
function ministering(){if(currentTab!=='Ministração'||document.querySelector('.sv2Min'))return;const ds=window.MINISTERING_DISTRICTS;if(!Array.isArray(ds))return;const interviews=state.ministeringV2?.interviews||[],q=Math.floor(new Date().getMonth()/3),y=new Date().getFullYear(),from=`${y}-${String(q*3+1).padStart(2,'0')}-01`,to=new Date(y,q*3+3,0).toISOString().slice(0,10);let total=0,done=0;const rows=ds.map(d=>{const n=d.companionships.length,x=d.companionships.filter(c=>interviews.some(i=>i.companionshipId===c.id&&i.date>=from&&i.date<=to&&(i.participants||[]).length)).length;total+=n;done+=x;return `<div><span>${E(d.name)}</span><b>${x}/${n}</b><i><em style="width:${n?Math.round(x/n*100):0}%"></em></i></div>`}).join('');const box=document.createElement('section');box.className='sv2Min';box.innerHTML=`<div class="sv2Head"><span>Visão rápida</span><b>${total?Math.round(done/total*100):0}% das companhias entrevistadas</b><small>${done} de ${total} neste trimestre</small></div><div class="sv2Bars">${rows}</div>`;document.querySelector('#view .hero')?.insertAdjacentElement('afterend',box)}
function convertsAttention(){if(currentTab!=='Recém-conversos'||document.querySelector('.sv2Convert'))return;const a=Array.isArray(converts)?converts:[],attention=a.filter(x=>x.nuncaEntrevistado||!x.ultimaEntrevista||String(x.ministradores||'').toLowerCase()==='não'||String(x.recomendacao||'').toLowerCase()==='não'||String(x.chamado||'').toLowerCase()==='não');if(!attention.length)return;const box=document.createElement('section');box.className='sv2Convert';box.innerHTML=`<div class="sv2Head"><span>Para acompanhar</span><b>${attention.length} ${attention.length===1?'pessoa merece':'pessoas merecem'} atenção</b><small>Indicadores do acompanhamento sincronizado</small></div><div class="sv2Names">${attention.slice(0,5).map(x=>`<button data-sv2-name="${E(x.nome)}">${E(x.nome)}</button>`).join('')}</div>`;document.querySelector('#view .hero')?.insertAdjacentElement('afterend',box)}
function run(){try{ministering();convertsAttention()}catch(e){console.warn('safe bundle v2 skipped',e)}}const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);requestAnimationFrame(run);return r};document.addEventListener('click',e=>{const n=e.target.closest('[data-sv2-name]');if(n){const cards=[...document.querySelectorAll('.convertCard')],card=cards.find(x=>x.textContent.includes(n.dataset.sv2Name));card?.scrollIntoView({behavior:'smooth',block:'center'});card?.querySelector('.convertToggle')?.click()}});document.addEventListener('DOMContentLoaded',()=>setTimeout(run,0));const s=document.createElement('style');s.textContent=`.sv2Min,.sv2Convert{background:var(--ios-card,#fff);border-radius:16px;padding:17px 18px;margin:0 0 14px;box-shadow:0 .5px 0 rgba(0,0,0,.06)}.sv2Head span,.sv2Head b,.sv2Head small{display:block}.sv2Head span{font-size:10px;text-transform:uppercase;letter-spacing:.055em;color:var(--teal);font-weight:750}.sv2Head b{font-size:17px;margin-top:3px}.sv2Bars{margin-top:13px}.sv2Bars>div{display:grid;grid-template-columns:1fr auto;gap:4px 10px;padding:7px 0}.sv2Bars span,.sv2Bars b{font-size:12px}.sv2Bars i{grid-column:1/-1;height:4px;border-radius:4px;background:#e7eceb;overflow:hidden}.sv2Bars em{display:block;height:100%;background:var(--teal);border-radius:4px}.sv2Names{display:flex;gap:7px;overflow:auto;margin-top:12px;padding-bottom:2px}.sv2Names button{border:0;background:#eef5f4;color:var(--teal);border-radius:999px;padding:8px 10px;white-space:nowrap;font-weight:650;font-size:11px}@media(prefers-color-scheme:dark){.sv2Bars i{background:#343436}.sv2Names button{background:#203b3a;color:#79d1cc}}`;document.head.appendChild(s)})();